interface Handler {
  setNext(handler: Handler): void;
  handle(req: Request): boolean;
}

class AuthHandler implements Handler {
  private next?: Handler;
  setNext(h: Handler) { this.next = h; }
  handle(req: Request) { if (req.user?.isAdmin) return true; return this.next ? this.next.handle(req) : false; }
}

type Request = { path: string; user?: any };
class Logger implements Handler { next?: Handler; setNext(h: Handler) { this.next = h; }
  handle(req: Request) { console.log(req.path); return this.next ? this.next.handle(req) : false; }
}
class Auth implements Handler { next?: Handler; setNext(h: Handler) { this.next = h; }
  handle(req: Request) { if (req.path.startsWith('/admin')) return this.checkAuth(req); return this.next ? this.next.handle(req) : false; }
}

// Version A: Monolithic dispatcher
class Router {
  handle(req: Request) {
    if (req.type === 'A') return this.handleA(req);
    if (req.type === 'B') return this.handleB(req);
    // many more conditionals
  }
}

// Version B: Composed handler components
interface Handler { setNext(h: Handler): void; handle(req: Request): boolean }
class HandlerA implements Handler { next?: Handler; setNext(h: Handler) { this.next = h; } handle(req: Request) { if (req.type === 'A') return true; return this.next ? this.next.handle(req) : false; } }
class HandlerB implements Handler { next?: Handler; setNext(h: Handler) { this.next = h; } handle(req: Request) { if (req.type === 'B') return true; return this.next ? this.next.handle(req) : false; } }
